css:
.hr-top,.hr-top *,main,main *,.hr-foot,.hr-foot *{box-sizing:border-box}
main{font-family:var(--page-sans),sans-serif;color:#17202a;background:#fff;font-size:16px;line-height:1.7;word-break:keep-all;overflow-wrap:break-word}
.hr-wrap{display:block;max-width:680px;margin:0 auto;padding:0 20px}
.hr-wrap.hr-wide{max-width:820px}
.hr-top{position:sticky;top:0;z-index:5;background:rgba(255,255,255,.95);border-bottom:1px solid #e3e8ef;font-family:var(--page-sans),sans-serif}
.hr-top-in{display:flex;justify-content:space-between;align-items:center;gap:12px;min-height:52px;max-width:820px}
.hr-brand{font-weight:700;color:#17202a}
.hr-top nav{display:flex;gap:4px;flex-wrap:wrap}
.hr-top a{display:inline-block;padding:8px 10px;color:#17202a;text-decoration:none;font-size:14px;border-radius:6px}
.hr-top a:hover{color:#2563eb;background:#eff4ff}
a:focus-visible,summary:focus-visible{outline:3px solid #2563eb;outline-offset:2px}
.hr-hero{padding:72px 0 56px}
.hr-label{font-family:var(--page-mono),monospace;font-size:13px;letter-spacing:.02em;color:#2563eb;margin:0 0 12px}
h1{font-family:var(--page-display),var(--page-sans),sans-serif;font-size:clamp(36px,8vw,60px);line-height:1.2;letter-spacing:-.02em;margin:0 0 24px;font-weight:700;color:#17202a}
h1 em{font-style:normal;color:#2563eb}
h2{font-size:clamp(24px,5vw,32px);line-height:1.35;letter-spacing:-.01em;margin:0 0 12px;color:#17202a}
h3{font-size:19px;line-height:1.4;margin:0 0 8px}
.hr-lead{font-size:18px;margin:0 0 32px}
.hr-kpis{display:block;list-style:none;margin:0 0 24px;padding:0;border:1px solid #d5dce8;border-radius:12px;overflow:hidden}
.hr-kpis li{display:grid;grid-template-columns:1fr auto;gap:2px 16px;padding:16px 20px;border-bottom:1px solid #e3e8ef;align-items:baseline}
.hr-kpis li:last-child{border-bottom:0}
.hr-k-name{display:block;font-size:15px;color:#4a5668}
.hr-k-val{display:block;font-family:var(--page-mono),monospace;font-size:17px;text-align:right;white-space:nowrap}
.hr-k-val b{color:#2563eb;font-size:22px}
.hr-k-val i{font-style:normal;color:#8591a3}
.hr-k-note{display:block;grid-column:1/-1;font-size:12px;color:#6b778a;text-align:right}
.hr-tags{font-size:14px;color:#4a5668;margin:0}
.hr-sec{padding:64px 0}
.hr-alt{background:#f5f8fe}
.hr-claim{font-size:18px;font-weight:600;color:#17202a;margin:0 0 16px;padding-left:14px;border-left:3px solid #2563eb}
.hr-sec p{margin:0 0 16px}
.hr-bars{display:block;background:#fff;border:1px solid #d5dce8;border-radius:12px;padding:8px 20px;margin-top:32px}
.hr-bar-row{display:block;padding:16px 0;border-bottom:1px solid #e3e8ef}
.hr-bar-row:last-child{border-bottom:0}
.hr-bar-h{display:flex;justify-content:space-between;flex-wrap:wrap;gap:4px 16px;font-weight:600;font-size:15px;margin-bottom:8px}
.hr-mono{font-family:var(--page-mono),monospace;font-weight:400;font-size:13px;color:#4a5668}
.hr-track{display:block;height:26px;background:#eef2f8;border-radius:6px;margin-bottom:6px;overflow:hidden}
.hr-before,.hr-after{display:block;height:100%;border-radius:6px;transform-origin:left;animation:hr-grow .9s ease-out both}
.hr-before{background:#c3ccdb}
.hr-after{background:#2563eb;animation-delay:.25s}
.hr-before span,.hr-after span{display:block;font-family:var(--page-mono),monospace;font-size:12px;line-height:26px;padding-left:10px;white-space:nowrap}
.hr-before span{color:#17202a}
.hr-after span{color:#fff}
@keyframes hr-grow{from{transform:scaleX(0)}to{transform:scaleX(1)}}
.hr-flow{display:block;margin:24px 0 0}
.hr-flow div{display:grid;grid-template-columns:96px 1fr;gap:16px;padding:14px 0;border-top:1px solid #e3e8ef}
.hr-flow dt{font-weight:700;color:#2563eb;font-size:15px}
.hr-flow dd{margin:0}
.hr-steps{list-style:none;counter-reset:s;margin:24px 0;padding:0}
.hr-steps li{counter-increment:s;position:relative;padding:0 0 18px 48px}
.hr-steps li::before{content:counter(s);position:absolute;left:0;top:0;width:32px;height:32px;border-radius:50%;background:#2563eb;color:#fff;display:block;text-align:center;line-height:32px;font-size:14px;font-family:var(--page-mono),monospace}
.hr-steps b{display:block}
.hr-callout{display:block;background:#fff;border:1px solid #d5dce8;border-left:4px solid #2563eb;border-radius:8px;padding:20px;margin-top:32px}
.hr-callout p:last-child{margin:0}
.hr-table{width:100%;border-collapse:collapse;margin-top:16px}
.hr-table th,.hr-table td{text-align:left;vertical-align:top;padding:14px 12px 14px 0;border-top:1px solid #d5dce8}
.hr-table th{width:30%;font-weight:700}
.hr-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
.hr-plain{list-style:none;margin:0;padding:0}
.hr-plain li{padding:12px 0;border-top:1px solid #d5dce8}
.hr-plain b{display:block}
.hr-job{display:block;border-top:2px solid #17202a;padding-top:16px}
.hr-date{margin:0 0 4px}
.hr-ev{list-style:none;margin:16px 0 0;padding:0}
.hr-ev li{border-top:1px solid #d5dce8}
.hr-ev li:last-child{border-bottom:1px solid #d5dce8}
.hr-ev summary{cursor:pointer;padding:14px 0;font-weight:600;list-style-position:inside}
.hr-ev summary:hover{color:#2563eb}
.hr-ev summary span{display:block;font-family:var(--page-mono),monospace;font-weight:400;font-size:12px;color:#4a5668;margin-top:2px}
.hr-ev details p{margin:0 0 16px;color:#33404f}
.hr-foot{padding:32px 0;border-top:1px solid #e3e8ef;font-size:14px;color:#4a5668;background:#fff;font-family:var(--page-sans),sans-serif}
.hr-foot p{margin:0}
@media (max-width:560px){.hr-hero{padding:48px 0 40px}.hr-sec{padding:48px 0}.hr-flow div{grid-template-columns:1fr;gap:2px}.hr-table th,.hr-table td{display:block;width:100%;padding:8px 0}.hr-table th{border-top:1px solid #d5dce8;padding-bottom:0}.hr-table td{border-top:0;padding-top:0}.hr-top nav a{padding:8px 6px}.hr-k-val{font-size:15px}.hr-k-val b{font-size:19px}}
@media (prefers-reduced-motion:reduce){.hr-before,.hr-after{animation:none}}
